#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <string>
#include <vector>

struct Change { std::size_t offset; std::size_t length; };

std::vector<Change> diffBytes(const std::vector<std::uint8_t>& before, const std::vector<std::uint8_t>& after)
{
    const std::size_t longest{ std::max(before.size(), after.size()) };
    const auto differs = [&](std::size_t i) {
        if (i >= before.size() || i >= after.size()) return true;
        return before[i] != after[i];
    };
    std::vector<Change> changes;
    std::size_t i{ 0 };
    while (i < longest)
    {
        if (!differs(i)) { ++i; continue; }
        const std::size_t start{ i };
        while (i < longest && differs(i)) ++i;
        changes.push_back({ start, i - start });
    }
    return changes;
}

static std::string hex(std::size_t value, int minDigits)
{
    static const char* const HEX{ "0123456789ABCDEF" };
    std::string out;
    do { out.insert(out.begin(), HEX[value & 0xF]); value >>= 4; } while (value);
    while (static_cast<int>(out.size()) < minDigits) out.insert(out.begin(), '0');
    return out;
}

static std::string side(const std::vector<std::uint8_t>& bytes, Change c)
{
    std::string out;
    for (std::size_t i{ c.offset }; i < c.offset + c.length; ++i)
    {
        if (i != c.offset) out += ' ';
        out += i < bytes.size() ? hex(bytes[i], 2) : "--";
    }
    return out;
}

std::string describe(const std::vector<std::uint8_t>& before, const std::vector<std::uint8_t>& after, Change c)
{
    return "0x" + hex(c.offset, 1) + ": " + side(before, c) + " -> " + side(after, c);
}

