using Bytes = std::vector<std::uint8_t>;
TEST("one changed run") {
    const Bytes a{ 0x55, 0x48, 0x89, 0xE5, 0x74, 0x05, 0x31, 0xC0 };
    Bytes b{ a };
    b[4] = 0xEB;
    const auto d{ diffBytes(a, b) };
    CHECK_EQ(d.size(), 1u);
    if (!d.empty()) { CHECK_EQ(d[0].offset, 4u); CHECK_EQ(d[0].length, 1u); }
    CHECK(diffBytes(a, a).empty());
}
TEST("several runs") {
    const Bytes a{ 1, 2, 3, 4, 5, 6, 7, 8 };
    const Bytes b{ 1, 9, 9, 4, 5, 6, 0, 8 };
    const auto d{ diffBytes(a, b) };
    CHECK_EQ(d.size(), 2u);
    if (d.size() == 2) { CHECK_EQ(d[0].offset, 1u); CHECK_EQ(d[0].length, 2u); CHECK_EQ(d[1].offset, 6u); CHECK_EQ(d[1].length, 1u); }
}
TEST("different lengths") {
    const Bytes a{ 1, 2, 3 };
    const Bytes b{ 1, 2, 7, 0x90, 0xC3 };
    const auto d{ diffBytes(a, b) };
    CHECK_EQ(d.size(), 1u);
    if (!d.empty()) { CHECK_EQ(d[0].offset, 2u); CHECK_EQ(d[0].length, 3u); }
    const auto e{ diffBytes(b, a) };
    CHECK_EQ(e.size(), 1u);
}
TEST("describing a change") {
    Bytes a(0x30, 0);
    a[0x1A] = 0x74; a[0x1B] = 0x05;
    Bytes b{ a };
    b[0x1A] = 0xEB;
    CHECK_EQ(describe(a, b, Change{ 0x1A, 2 }), std::string("0x1A: 74 05 -> EB 05"));
    const Bytes shortOne{ 0xCC };
    const Bytes longer{ 0xCC, 0x90, 0xC3 };
    CHECK_EQ(describe(shortOne, longer, Change{ 1, 2 }), std::string("0x1: -- -- -> 90 C3"));
}

